ModuleNotFoundError and sys.exit:
import sys
try:
    import nonexistentModule
except ModuleNotFoundError as err:
    print('Result: no module called', err.name)
    try:
        sys.exit('This program needs nonexistentModule.')
    except SystemExit as stop:
        print('exit message:', stop.code)

Clipboard recorder loop:
texts = ['ch11', 'ch11', 'ch12', 'ch12', 'ch13']
previous_content, recorded = '', []
try:
    for content in texts:  # the book calls paste()
        if content != previous_content:
            print(content)
            recorded.append(content)
            previous_content = content
    raise KeyboardInterrupt  # the user presses CTRL-C
except KeyboardInterrupt:
    print('Result: stopped quietly;', len(recorded), 'recorded')

